(function () {
  /**
 * ИМТ (BMI) = масса (кг) / рост (м)²
 * Классификация: ВОЗ, взрослые ≥18 лет.
 * При ИМТ ≥ 25 — антропометрические критерии (окружность талии, ОТ/ОБ, ОТ/рост).
 */

const SEX_OPTIONS = [
  { value: 'male', label: 'Мужской' },
  { value: 'female', label: 'Женский' },
];

/** Пороги для лиц европеоидной расы */
const ANTHRO_THRESHOLDS = {
  waistCm: { male: 102, female: 88 },
  whr: { male: 0.9, female: 0.85 },
  whtr: 0.5,
};

function defaultInputs() {
  return {
    weightKg: '',
    heightCm: '',
    sex: 'male',
    waistCm: '',
    hipCm: '',
  };
}

function parsePositive(raw) {
  const n = Number(String(raw ?? '').trim().replace(',', '.'));
  if (!Number.isFinite(n) || n <= 0) return null;
  return n;
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

function round3(n) {
  return Math.round(n * 1000) / 1000;
}

function formatRu(n, digits = 2) {
  return n.toFixed(digits).replace('.', ',');
}

/** Как на farmconsilium: границы через <= (18,5 и 25 попадают в «нижнюю» категорию таблицы). */
function interpretBmi(bmi) {
  if (bmi <= 16) return 'Выраженный дефицит массы тела';
  if (bmi <= 18.5) return 'Недостаточная (дефицит) масса тела';
  if (bmi <= 25) return 'Норма';
  if (bmi <= 30) return 'Избыточная масса тела (предожирение)';
  if (bmi <= 35) return 'Ожирение первой степени';
  if (bmi <= 40) return 'Ожирение второй степени';
  return 'Ожирение третьей степени (морбидное)';
}

function categoryKey(bmi) {
  if (bmi <= 18.5) return 'underweight';
  if (bmi <= 25) return 'normal';
  if (bmi <= 30) return 'overweight';
  return 'obese';
}

function needsAnthropometry(bmi) {
  return Number.isFinite(bmi);
}

/** Рекомендации при избыточной массе / ожирении (ИМТ > 25). */
function buildRecommendations(weightKg, bmi) {
  if (!Number.isFinite(bmi) || bmi <= 25) return null;
  if (!Number.isFinite(weightKg) || weightKg <= 0) return null;

  const loss5 = round2(weightKg * 0.05);
  const loss10 = round2(weightKg * 0.1);
  const targetHigh = round2(weightKg - loss5);
  const targetLow = round2(weightKg - loss10);

  return {
    items: [
      `Цель: снизить массу на 5–10% за 3–6 месяцев терапии и удержать результат в течение года (ориентир: −${formatRu(loss5, loss5 % 1 === 0 ? 0 : 1)}…−${formatRu(loss10, loss10 % 1 === 0 ? 0 : 1)} кг → ${formatRu(targetLow, targetLow % 1 === 0 ? 0 : 1)}–${formatRu(targetHigh, targetHigh % 1 === 0 ? 0 : 1)} кг).`,
      'Обязательные обследования: ОАК, ОАМ, биохимический анализ крови (глюкоза плазмы, липидограмма, функция почек и печени), ЭКГ, ТТГ.',
      'Немедикаментозное лечение: модификация образа жизни — индивидуализация целей, поэтапное снижение веса, контроль факторов риска и сопутствующих заболеваний; мотивационное консультирование и обучение пациента.',
      'Наблюдение: в среднем 1 раз в месяц первые 3 месяца, затем 1 раз в 3 месяца в течение первого года, далее не реже 1 раза в 6 месяцев (план лечения, мотивация, антропометрия, клиника).',
    ],
    loss5Kg: loss5,
    loss10Kg: loss10,
    targetWeightLowKg: targetLow,
    targetWeightHighKg: targetHigh,
  };
}

/**
 * Оценка антропометрических критериев избыточного накопления жировой ткани.
 * Положительный критерий — значение на пороге или выше (для ОТ) / строго выше (для отношений).
 */
function evaluateAnthropometry({ sex, waistCm, hipCm, heightCm }) {
  const s = sex === 'female' ? 'female' : 'male';
  const waist = Number(waistCm);
  const hip = Number(hipCm);
  const height = Number(heightCm);

  if (!Number.isFinite(waist) || waist <= 0) {
    throw new Error('Укажите окружность талии');
  }
  if (!Number.isFinite(hip) || hip <= 0) {
    throw new Error('Укажите окружность бёдер');
  }
  if (!Number.isFinite(height) || height <= 0) {
    throw new Error('Укажите рост');
  }

  const waistLimit = ANTHRO_THRESHOLDS.waistCm[s];
  const whrLimit = ANTHRO_THRESHOLDS.whr[s];
  const whtrLimit = ANTHRO_THRESHOLDS.whtr;

  const whr = round3(waist / hip);
  const whtr = round3(waist / height);

  const waistElevated = waist >= waistLimit;
  const whrElevated = whr > whrLimit;
  const whtrElevated = whtr > whtrLimit;
  const confirmed = waistElevated || whrElevated || whtrElevated;

  return {
    sex: s,
    waistCm: round2(waist),
    hipCm: round2(hip),
    heightCm: round2(height),
    waistLimit,
    whr,
    whrLimit,
    whtr,
    whtrLimit,
    waistElevated,
    whrElevated,
    whtrElevated,
    confirmed,
    summary: confirmed
      ? 'Избыточное накопление жировой ткани подтверждено (≥1 критерий)'
      : 'Критерии избыточного накопления жировой ткани не выполнены',
  };
}

function calculateBsaDubois(weightKg, heightCm) {
  const bsa = (Math.pow(weightKg, 0.425) * Math.pow(heightCm, 0.725)) / 139.2;
  const value = Math.round(bsa * 100) / 100;
  return {
    bsaM2: value,
    bsaLabel: formatRu(value),
  };
}

function isReady(input) {
  const w = parsePositive(input?.weightKg);
  const h = parsePositive(input?.heightCm);
  return w != null && h != null;
}

function isAnthroReady(input) {
  return (
    parsePositive(input?.waistCm) != null && parsePositive(input?.hipCm) != null
  );
}

function calculate(input) {
  const weightKg = parsePositive(input?.weightKg) ?? Number(input?.weightKg);
  const heightCm = parsePositive(input?.heightCm) ?? Number(input?.heightCm);

  if (!Number.isFinite(weightKg) || weightKg <= 0 || weightKg > 500) {
    throw new Error('Укажите массу от 1 до 500 кг');
  }
  if (!Number.isFinite(heightCm) || heightCm < 50 || heightCm > 250) {
    throw new Error('Укажите рост от 50 до 250 см');
  }

  const heightM = heightCm / 100;
  const bmi = weightKg / (heightM * heightM);
  // как на farmconsilium: toFixed(2), без Math.round — одинаковое отображение
  const valueLabel = bmi.toFixed(2);
  const value = Number(valueLabel);
  const needsAnthro = needsAnthropometry(bmi);
  const { bsaM2, bsaLabel } = calculateBsaDubois(weightKg, heightCm);

  const result = {
    value,
    valueLabel,
    interpretation: interpretBmi(bmi),
    category: categoryKey(bmi),
    needsAnthropometry: needsAnthro,
    heightCm: round2(heightCm),
    weightKg: round2(weightKg),
    bsaM2,
    bsaLabel,
    recommendations: buildRecommendations(weightKg, bmi),
    anthropometry: null,
  };

  if (needsAnthro && isAnthroReady(input)) {
    result.anthropometry = evaluateAnthropometry({
      sex: input?.sex,
      waistCm: parsePositive(input.waistCm),
      hipCm: parsePositive(input.hipCm),
      heightCm,
    });
  }

  return result;
}

    var FIGURE_SRC = {
    male: 'data:image/png;base64,',
    female: 'data:image/png;base64,',
  };

  var root = document.querySelector('.fc-calc[data-calculator="bmi"]');
  if (!root) return;

  var form = root.querySelector('#fc-calc-bmi-form');
  var heightInput = root.querySelector('#fc-calc-bmi-height');
  var weightInput = root.querySelector('#fc-calc-bmi-weight');
  var waistInput = root.querySelector('#fc-calc-bmi-waist');
  var hipInput = root.querySelector('#fc-calc-bmi-hip');
  var formError = root.querySelector('#fc-calc-bmi-form-error');
  var anthroBlock = root.querySelector('#fc-calc-bmi-anthro');
  var resultWrap = root.querySelector('#fc-calc-bmi-result');
  var resultNumber = root.querySelector('#fc-calc-bmi-result-number');
  var resultDesc = root.querySelector('#fc-calc-bmi-result-desc');
  var bsaValue = root.querySelector('#fc-calc-bmi-bsa-value');
  var figureImg = root.querySelector('#fc-calc-bmi-figure-img');
  var tagWeight = root.querySelector('#fc-calc-bmi-tag-weight');
  var tagHeight = root.querySelector('#fc-calc-bmi-tag-height');
  var tagWaist = root.querySelector('#fc-calc-bmi-tag-waist');
  var tagHip = root.querySelector('#fc-calc-bmi-tag-hip');
  var recBlock = root.querySelector('#fc-calc-bmi-recommendations');
  var recList = root.querySelector('#fc-calc-bmi-recommendations-list');
  var anthroResult = root.querySelector('#fc-calc-bmi-anthro-result');
  var anthroSummary = root.querySelector('#fc-calc-bmi-anthro-summary');
  var critWaist = root.querySelector('#fc-calc-bmi-crit-waist');
  var critWhr = root.querySelector('#fc-calc-bmi-crit-whr');
  var critWhtr = root.querySelector('#fc-calc-bmi-crit-whtr');

  function buildInput() {
    var checked = form.querySelector('input[name="sex"]:checked');
    return {
      sex: checked ? checked.value : 'male',
      heightCm: heightInput.value,
      weightKg: weightInput.value,
      waistCm: waistInput ? waistInput.value : '',
      hipCm: hipInput ? hipInput.value : '',
    };
  }

  function formatCmTag(raw) {
    var n = parsePositive(raw);
    if (n == null) return '—';
    var digits = n % 1 === 0 ? 0 : 1;
    return formatRu(n, digits) + ' см';
  }

  function formatKgTag(raw) {
    var n = parsePositive(raw);
    if (n == null) return '—';
    var digits = n % 1 === 0 ? 0 : 1;
    return formatRu(n, digits) + ' кг';
  }

  function updateFigure(sex) {
    if (!figureImg) return;
    var key = sex === 'female' ? 'female' : 'male';
    figureImg.src = FIGURE_SRC[key];
    figureImg.alt =
      key === 'female'
        ? 'Схема измерения роста, окружности талии и бёдер (женщины)'
        : 'Схема измерения роста, окружности талии и бёдер (мужчины)';
    if (resultWrap) resultWrap.style.backgroundImage = '';
  }

  function updateFigureTags(input) {
    if (tagWeight) tagWeight.textContent = formatKgTag(input.weightKg);
    if (tagHeight) tagHeight.textContent = formatCmTag(input.heightCm);
    if (tagWaist) tagWaist.textContent = formatCmTag(input.waistCm);
    if (tagHip) tagHip.textContent = formatCmTag(input.hipCm);
  }

  function setCriterion(el, name, valueText, elevated, thresholdText) {
    if (!el) return;
    el.classList.toggle('fc-calc__bmi-criterion--yes', !!elevated);
    el.classList.toggle('fc-calc__bmi-criterion--no', !elevated);
    el.querySelector('.fc-calc__bmi-criterion-name').textContent = name;
    el.querySelector('.fc-calc__bmi-criterion-value').textContent = valueText;
    el.querySelector('.fc-calc__bmi-criterion-flag').textContent = elevated
      ? 'Критерий (+)'
      : 'Норма';
    el.title = thresholdText || '';
  }

  function clearAnthroResult() {
    if (anthroResult) anthroResult.hidden = true;
    if (anthroSummary) {
      anthroSummary.textContent = '';
      anthroSummary.classList.remove(
        'fc-calc__bmi-anthro-summary--yes',
        'fc-calc__bmi-anthro-summary--no'
      );
    }
  }

  function clearRecommendations() {
    if (recList) recList.innerHTML = '';
    if (recBlock) recBlock.hidden = true;
  }

  function renderRecommendations(rec) {
    if (!recBlock || !recList || !rec || !rec.items || !rec.items.length) {
      clearRecommendations();
      return;
    }
    recList.innerHTML = '';
    rec.items.forEach(function (text) {
      var li = document.createElement('li');
      li.textContent = text;
      recList.appendChild(li);
    });
    recBlock.hidden = false;
  }

  function setResultTone(category) {
    var tones = ['underweight', 'normal', 'overweight', 'obese'];
    tones.forEach(function (tone) {
      resultNumber.classList.toggle('fc-calc__bmi-result-number--' + tone, category === tone);
      resultDesc.classList.toggle('fc-calc__bmi-result-desc--' + tone, category === tone);
    });
  }

  function clearResult() {
    resultWrap.classList.add('fc-calc__result-wrap--hidden');
    resultNumber.textContent = '—';
    resultDesc.textContent = '—';
    if (bsaValue) bsaValue.textContent = '—';
    setResultTone('');
    clearRecommendations();
    if (anthroBlock) anthroBlock.hidden = true;
    clearAnthroResult();
  }

  function renderAnthro(a) {
    if (!a || !anthroResult) {
      clearAnthroResult();
      return;
    }

    var sexLabel = a.sex === 'female' ? 'жен.' : 'муж.';
    setCriterion(
      critWaist,
      'Окружность талии',
      formatRu(a.waistCm, a.waistCm % 1 === 0 ? 0 : 1) + ' см',
      a.waistElevated,
      'Порог (' + sexLabel + '): ≥ ' + a.waistLimit + ' см'
    );
    setCriterion(
      critWhr,
      'Соотношение окружности талии к окружности бёдер',
      formatRu(a.whr, 3),
      a.whrElevated,
      'Порог (' + sexLabel + '): > ' + formatRu(a.whrLimit, 2)
    );
    setCriterion(
      critWhtr,
      'Соотношение окружности талии к росту',
      formatRu(a.whtr, 3),
      a.whtrElevated,
      'Порог: > ' + formatRu(a.whtrLimit, 1)
    );

    anthroSummary.textContent = a.summary;
    anthroSummary.classList.toggle('fc-calc__bmi-anthro-summary--yes', a.confirmed);
    anthroSummary.classList.toggle('fc-calc__bmi-anthro-summary--no', !a.confirmed);
    anthroResult.hidden = false;
  }

  function renderResult(out) {
    var input = buildInput();
    resultNumber.textContent = out.valueLabel;
    resultDesc.textContent = out.interpretation;
    if (bsaValue) bsaValue.textContent = out.bsaLabel + ' м²';
    setResultTone(out.category);
    updateFigure(input.sex);
    updateFigureTags(input);
    resultWrap.classList.remove('fc-calc__result-wrap--hidden');
    renderRecommendations(out.recommendations);

    if (anthroBlock) {
      anthroBlock.hidden = !out.needsAnthropometry;
    }

    if (out.needsAnthropometry && out.anthropometry) {
      renderAnthro(out.anthropometry);
    } else {
      clearAnthroResult();
    }
  }

  function update() {
    formError.textContent = '';
    if (!isReady(buildInput())) {
      clearResult();
      return;
    }
    try {
      renderResult(calculate(buildInput()));
    } catch (err) {
      clearResult();
      formError.textContent = err.message || 'Проверьте ввод';
    }
  }

  form.querySelectorAll('input[name="sex"]').forEach(function (el) {
    el.addEventListener('change', update);
  });
  [heightInput, weightInput, waistInput, hipInput].forEach(function (el) {
    if (!el) return;
    el.addEventListener('input', update);
    el.addEventListener('change', update);
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    update();
  });

  updateFigure('male');
  update();

})();